from datetime import timedelta

from django.db import migrations, models
from django.db.models import Sum


def preencher(apps, schema_editor):
    """Faturas de comissões já registadas: o valor que cobrem é o do mês agora (comissões menos créditos)."""
    FaturaComissoes = apps.get_model('app', 'FaturaComissoes')
    Comissao = apps.get_model('app', 'Comissao')
    CreditoComissao = apps.get_model('app', 'CreditoComissao')
    for fc in FaturaComissoes.objects.all():
        seguinte = (fc.mes.replace(day=28) + timedelta(days=4)).replace(day=1)
        qs = Comissao.objects.filter(loja_id=fc.loja_id, data_criacao__date__gte=fc.mes, data_criacao__date__lt=seguinte)
        total = qs.aggregate(t=Sum('valor_comissao'))['t'] or 0
        cred = CreditoComissao.objects.filter(comissao__in=qs.values('id')).aggregate(t=Sum('valor'))['t'] or 0
        fc.valor_faturado = total - cred
        fc.save(update_fields=['valor_faturado'])


